const DEFAULT_URL='http://127.0.0.1:5174';
export class LiveClient{
  constructor({url=DEFAULT_URL,fetcher=globalThis.fetch?.bind(globalThis),storage=globalThis.sessionStorage}={}){this.url=url;this.fetcher=fetcher;this.storage=storage;this.token=storage?.getItem('ricing-town.helper-token')||'';this.listeners=new Set();this.status='disconnected';this.data=null;this.capabilities=null;this.timer=null;this.streamController=null;this.failures=0;this.backoff=500;this.lastSequence=0;}
  emit(){for(const fn of this.listeners)fn(this);}
  subscribe(fn){this.listeners.add(fn);return()=>this.listeners.delete(fn);}
  async request(path,{method='GET',body,authenticated=true}={}){const headers={'Content-Type':'application/json','X-Ricing-Town-Protocol':'1'};if(authenticated&&this.token)headers.Authorization='Bearer '+this.token;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),2500);try{const response=await this.fetcher(this.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal,cache:'no-store'});const result=await response.json().catch(()=>({error:{code:'invalid_response',message:'Helper returned invalid JSON'}}));if(!response.ok)throw Object.assign(Error(result.error?.message||'Helper request failed'),{code:result.error?.code,status:response.status});return result;}finally{clearTimeout(timeout);}}
  async pair(code){if(!/^\d{6}$/.test(code))throw Error('Pairing code must contain 6 digits');const result=await this.request('/v1/pair',{method:'POST',body:{code},authenticated:false});this.token=result.token;this.storage?.setItem('ricing-town.helper-token',this.token);await this.connect();return result;}
  async connect(){this.status='loading';this.emit();try{this.capabilities=await this.request('/v1/capabilities');this.failures=0;this.status='connected';await this.refresh();this.start();}catch(error){this.status=error.status===401?'unpaired':'disconnected';this.emit();throw error;}}
  start(){clearTimeout(this.timer);if(this.capabilities?.protocol>=2){this.stream();return;}const tick=async()=>{try{await this.refresh();this.failures=0;}catch{this.failures++;this.status=this.failures>2?'disconnected':'stale';this.emit();}this.timer=setTimeout(tick,this.status==='connected'?1500:4000);};this.timer=setTimeout(tick,1500);}
  async stream(){this.streamController?.abort();const controller=new AbortController();this.streamController=controller;try{const response=await this.fetcher(this.url+'/v1/events',{headers:{Authorization:'Bearer '+this.token,'X-Ricing-Town-Protocol':'2'},signal:controller.signal,cache:'no-store'});if(!response.ok||!response.body)throw Error('Event stream unavailable');const reader=response.body.getReader(),decoder=new TextDecoder();let pending='';for(;;){const{done,value}=await reader.read();if(done)throw Error('Event stream closed');pending+=decoder.decode(value,{stream:true});const lines=pending.split('\n');pending=lines.pop();for(const line of lines){if(!line)continue;const message=JSON.parse(line);if(message.sequence<=this.lastSequence)continue;this.lastSequence=message.sequence;if(message.data){this.data=message.data;this.status='connected';this.backoff=500;this.emit();}}}}catch(error){if(controller.signal.aborted)return;this.status=this.data?'stale':'disconnected';this.emit();const delay=Math.min(30000,this.backoff)+Math.random()*300;this.backoff=Math.min(30000,this.backoff*2);this.timer=setTimeout(()=>this.stream(),delay);}}
  disconnect(){clearTimeout(this.timer);this.streamController?.abort();this.streamController=null;this.timer=null;this.status='disconnected';this.emit();}
  async refresh(){const result=await this.request('/v1/snapshot');this.data=result.data;this.status='connected';this.emit();return this.data;}
  async execute(value,{confirm=false}={}){const validated=validateLiveAction(value);const result=await this.request('/v1/actions',{method:'POST',body:{action:validated,confirm}});if(!result.ok)throw Error(result.error?.message||'Action failed');await this.refresh();return result;}
}
export function validateLiveAction(a){if(!a||typeof a!=='object'||!['launch','workspace','volumeSet','volumeStep','muteToggle','media','power'].includes(a.type))throw Error('Unsupported live action');return a;}
